const cols = ["id", "area", "feature", "emdash", "emdashConfidence", "status", "kit", "gap", "effort", "risk", "priority", "sitesUsed"];
const rows = R.map((r) => Object.fromEntries(cols.map((c, i) => [c, r[i]])));
for (const r of rows) if (r.length !== undefined) throw new Error("bad row");
for (const r of R) if (r.length !== cols.length) throw new Error(`row ${r[0]} has ${r.length} cells`);

const inScope = rows.filter((r) => r.status !== "oos");
const count = (s) => inScope.filter((r) => r.status === s).length;
const pct = (n) => `${Math.round((n / inScope.length) * 100)}%`;
const summary = { areas: rows.length, inScope: inScope.length, done: count("done"), superseded: count("superseded"), partial: count("partial"), missing: count("missing"), outOfScope: rows.length - inScope.length };

const backlog = [
	// [rank, priority, title, rows, effort, notes]
	[1, "P0", "Posts collection: Gutenberg/classic → Portable Text (EmDash converter + kit shortcode pass), dates, excerpt, featured image, permalinks, `?p=` for posts", ["posts", "post-dates", "post-permalinks", "excerpt", "featured-image", "wp-ids"], "L", "Done 2026-11-20 (blog milestone, docs/spikes/blog-findings.md): posts collection, EmDash converter + shortcode pass, dates, excerpt, featured image, sticky, scheduled, permalinks, `?p=` for posts."],
	[2, "P0", "Verify every audited URL: 200, single-hop 301 to a mapped target, or 410 with a decision", ["archive-urls"], "M", "Done 2026-11-20: verify `urls-accounted` (docs/spikes/wp-urls-findings.md)."],
	[3, "P0", "List every non-empty unhandled post type in coverage + transform gate", ["cpt"], "S", "Done 2026-11-20: transform `content-types-handled` (types, taxonomies in use, authors with posts; `overrides.ts contentTypes` skip | pages)."],
	[4, "P0", "Taxonomies: defs, terms, assignments", ["categories-tags", "custom-taxonomies"], "M", "Done 2026-11-20 for categories, tags and taxonomies of posts (hierarchy kept). Taxonomies of CPTs come with item 8."],
	[5, "P0", "Bylines from WordPress authors", ["bylines"], "M", "Done 2026-11-20: guest bylines (name, bio, site-hosted avatar), no user accounts; the load token needs the `admin` scope."],
	[6, "P0", "Starter blog templates: single post, blog index, category/tag/author archives, pagination", ["archives", "single-post"], "M", "Done 2026-11-20: posts page, archives at the WordPress bases, `/page/N/`, single post with prev/next and related, archives sitemap."],
	[7, "P0", "Feeds: `/feed/` + category feeds from posts; redirect/410 rule and verify check for sites without posts", ["rss"], "S", "Done 2026-11-20: RSS 2.0 site and archive feeds with autodiscovery (verify `feeds`); sites without posts keep the 301/410 rule."],
	[8, "P0", "Custom post type mapper (collection per type, fields, urlPattern, templates)", ["cpt"], "L", "Done 2026-11-21 (docs/spikes/cpt-findings.md): collection per public type, core fields, permalinks, archives, term archives, references, seed/load/verify; tested on a synthetic site and a local EmDash end to end."],
	[9, "P1", "Search page + `/?s=` redirect; other WP query URLs (`?cat`, `?tag`, `?author`, `?attachment_id`, `?feed`) and attachment pages", ["search", "wp-query-urls", "attachment-pages"], "S", "Done 2026-11-20; the search page 2026-11-21 (`/search/?q=`, EmDash FTS + page sections; `?s=` 301s there)."],
	[10, "P1", "Comments import (spike the write path first)", ["comments", "comment-settings"], "M", "Done 2026-11-21 (docs/spikes/comments-findings.md): kit import route writes pending rows, EmDash's bulk moderation approves; settings per collection; starter list + form; tested on a synthetic blog and a local EmDash."],
	[11, "P1", "Third-party scripts: snippet recognizer (in progress), consent banner, chat/embeds allowlist, Customizer CSS", ["snippets", "consent", "custom-css", "embeds", "widgets-3p"], "M", "The consent banner is P0 for EU/UK clients. Embeds done 2026-11-21 (oEmbed URLs → official markup, nine more providers). Customizer CSS done 2026-11-20 (reported, carried by decision)."],
	[12, "P1", "Elementor adapter", ["elementor"], "L", "Most common builder after Gutenberg."],
	[13, "P1", "DOM-fallback adapter (any builder, flagged)", ["other-builders"], "L", "Built 2026-11-21 (docs/spikes/dom-fallback-findings.md): rendered HTML → sections, flagged and gated until the owner reviews each page; not yet run on a real site."],
	[14, "P1", "ACF / Meta Box / Pods field mapping", ["acf"], "L", "Done 2026-11-21 with item 8: field definitions from exports, ACF posts and the Exporter; unsupported types as JSON + warning; unknown meta gated (`cpt-fields`)."],
	[15, "P1", "Settings into EmDash: logo, favicon, social, robots.txt rules, timezone, date format, posts per page (EmDash Settings prefill in progress)", ["logo-favicon", "social", "robots", "display-settings"], "S", "Lets the owner edit identity in the admin."],
	[16, "P1", "Menus: write every menu, link items to entries", ["menus", "mega-menu"], "S", "Done 2026-11-21: every menu, classes, title attribute, targets, depth; mega menus as columns (partial)."],
	[17, "P1", "Widgets / sidebars", ["widgets"], "M", "Done 2026-11-21 (docs/spikes/site-features-findings.md); not yet on a real classic-theme site."],
	[18, "P1", "Media completeness: upload library-only files and PDFs linked in content", ["media-files", "pdf"], "S", "Done 2026-11-21 (content & forms batch): linked documents, library documents, captions, dedupe report."],
	[19, "P1", "Divi adapter", ["divi"], "L", "Reuses the shortcode parser."],
	[20, "P1", "Gutenberg: core file/audio, block libraries (Kadence, Spectra, GenerateBlocks)", ["gutenberg", "gutenberg-libs"], "M", "Core file/audio and latest-posts/query loop (`audio`, `posts_list` sections) done 2026-11-21."],
	[21, "P1", "Scheduled and password-protected content", ["scheduled", "password-protected"], "M", "Password-protected and private content done 2026-11-21 (password page, hashed WordPress password)."],
	[22, "P1", "Off-account backups (scheduled site export + R2)", ["backups"], "M", ""],
	[23, "P1", "Forms: Ninja/Formidable/Elementor extractors, file uploads, conditional logic", ["forms-other", "forms-features"], "M", "Done 2026-11-21: Ninja, Formidable, WS Form, Forminator, HTML fallback; forms 1.7 uploads, conditions, steps."],
	[24, "P1", "Post-launch 404 → redirect suggestions; sitemaps for posts/terms", ["404-log", "sitemaps"], "S", "404 monitoring done 2026-11-21 (Site health → Missing pages). Image sitemap entries 2026-11-21 (each entry's SEO image, the featured image when there is no og:image)."],
	[25, "P2", "P2 batch: invite list from WordPress users, term descriptions, page order/parent/excerpt/featured image, reusable blocks as sections, oEmbed providers, Adobe Fonts in the CSP, form-entries checklist", ["users", "term-meta", "menu-order", "page-hierarchy", "featured-image", "excerpt", "reusable-blocks", "embeds", "fonts", "form-entries"], "M", "Done 2026-11-21 (docs/spikes/p2-batch-findings.md) except term SEO (no per-term store in EmDash 1.5) and parent renames moving children."],
	[26, "P2", "Media folders from FileBird, Real Media Library and attachment taxonomies", ["media-folders"], "S", "Done 2026-11-21 (docs/spikes/media-folders-findings.md); not yet on a real site."],
];
const p2 = rows.filter((r) => r.priority === "P2").map((r) => r.id);
const oos = rows.filter((r) => r.priority === "OOS" || r.status === "oos");

const json = {
	$comment: "Generated with docs/parity/wp-to-emdash.md. Status: done | partial | missing | superseded | oos. emdashConfidence: src (installed emdash 1.5.0 source) | docs | none (not in EmDash; theme/kit builds it). sitesUsed: of the two migrated real sites.",
	generated: "2026-11-21",
	emdashVersion: "1.5.0",
	summary,
	rows,
	backlog: backlog.map(([rank, priority, title, ids, effort, notes]) => ({ rank, priority, title, rows: ids, effort, notes })),
	p2,
	outOfScope: oos.map((r) => ({ id: r.id, feature: r.feature, reason: r.gap })),
};
writeFileSync(`${OUT}/wp-to-emdash.json`, JSON.stringify(json, null, "\t") + "\n");

// ── Markdown ───────────────────────────────────────────────────────────────
const esc = (s) => String(s).replace(/\|/g, "\\|").replace(/\n/g, " ");
const STATUS = { done: "✅ done", partial: "🟡 partial", missing: "❌ missing", superseded: "➖ superseded", oos: "⛔ out of scope" };
const CONF = { src: "", docs: " *(docs)*", none: " *(not in EmDash)*" };
const areas = [...new Set(rows.map((r) => r.area))];
const L = [];
L.push(`# WordPress → EmDash parity`, "");
L.push(`What a small-business or content WordPress site can contain, where each thing lives in EmDash 1.5.0, what the kit does with it today, and what closing each gap takes. The same data is in [\`wp-to-emdash.json\`](./wp-to-emdash.json); keep the two in sync.`, "");
L.push(`As of 2026-11-20, against EmDash 1.5.0 (installed source) and the kit at that date. Evidence from real sites is counted across the two migrated sites only, with no client details. Status values: ✅ done · 🟡 partial · ❌ missing · ➖ superseded (the platform replaces the WordPress feature, so nothing has to be carried) · ⛔ out of scope. Effort: S ≤ 1 day, M = 2–5 days, L = 1–3 weeks.`, "");
L.push(`## 1. Executive summary`, "");
L.push(`The matrix covers ${summary.areas} features; ${summary.inScope} of them are in scope.`, "");
L.push(`| | Count | Share of in-scope |`, `|---|---|---|`);
L.push(`| ✅ Done | ${summary.done} | ${pct(summary.done)} |`);
L.push(`| ➖ Superseded (nothing to carry) | ${summary.superseded} | ${pct(summary.superseded)} |`);
L.push(`| 🟡 Partial | ${summary.partial} | ${pct(summary.partial)} |`);
L.push(`| ❌ Missing | ${summary.missing} | ${pct(summary.missing)} |`);
L.push(`| ⛔ Out of scope (not counted) | ${summary.outOfScope} | — |`, "");
L.push(`**What this means.** The kit fully migrates a brochure site: builder pages (WPBakery/Salient, Bricks, Gutenberg pages; Elementor, Divi and the Gutenberg block libraries since 2026-11-21, not yet on a real site), header and footer, menus, popups and announcement bars, media in use, forms, SEO meta, JSON-LD, analytics, redirects from plugin exports, and old upload/sitemap/\`?page_id\` URLs. Both real sites were exactly that. They had no posts, comments, CPT entries, terms in use, widgets, consent banner or redirect rules. Since 2026-11-20 the kit also migrates a blog: posts, categories and tags, bylines, archives and RSS feeds (tested on a synthetic WordPress blog and a local EmDash, not yet on a real blog). Since 2026-11-21 custom post types become their own collections with their ACF, Meta Box and Pods fields, archives and term archives (tested the same way).`, "");
L.push(`Anything beyond that is missing today. Since 2026-11-21 approved comments are migrated too, with their date, author and threads (synthetic test). Since 2026-11-21 the site features are carried too: every menu, classic widget areas, a search page, breadcrumbs, the old 404 page. The kit has no adapters for other builders (the Elementor and Divi adapters exist since 2026-11-21 but have not met a real site yet); a built-in consent banner exists since 2026-11-20. Since 2026-11-20 none of it is lost silently: transform lists every unmigrated post type, taxonomy in use and author (gate \`content-types-handled\`), Customizer CSS is reported and carried by decision, and verify accounts for every old address (\`urls-accounted\`): feeds, search, archives, attachment pages and query URLs follow a per-site rule set.`, "");
L.push(`**Top 10 gaps by impact**`, "");
const top = [
	"**~~Blog posts are not migrated.~~** Closed 2026-11-20 (blog milestone). Rows: posts, post-dates, post-permalinks, excerpt, featured-image.",
	"**~~Verify ignores audited URLs that are not migrated pages.~~** Closed 2026-11-20: verify `urls-accounted` checks every audited, discovered and WordPress-form URL. Row: archive-urls.",
	"**~~Custom post types are not migrated.~~** Closed 2026-11-21 (CPT mapper): a collection per public type with its ACF, Meta Box and Pods fields, archives and term archives. Rows: cpt, acf.",
	"**~~Categories, tags and custom taxonomies are extracted but never loaded.~~** Closed 2026-11-20 for posts and 2026-11-21 for custom post types. Rows: categories-tags, custom-taxonomies.",
	"**~~No authors or bylines.~~** Closed 2026-11-20 (guest bylines). Row: bylines.",
	"**~~The starter has no search page.~~** Closed 2026-11-21: `/search/?q=` with EmDash full-text search; `?s=` goes there. Row: search.",
	"**~~No RSS feeds.~~** Closed 2026-11-20: blog sites serve RSS 2.0 site and archive feeds. Row: rss.",
	"**~~Comments are extracted but not loaded.~~** Closed 2026-11-21: approved comments with date, author and threads through an admin-only import route, approved by EmDash's moderation. Row: comments.",
	"**Third-party scripts now have a home.** The snippet recognizer, the 46-provider registry, site widgets and the built-in consent banner carry them; unknown code still waits for a decision (gate `site-snippets`).",
	"**Five builders have adapters.** WPBakery/Salient, Gutenberg (with Kadence, Spectra, GenerateBlocks, Stackable and CoBlocks blocks), Bricks and (since 2026-11-21, unmeasured on a real site) Elementor and Divi. Pages of any other builder or theme go through the DOM fallback (2026-11-21, unmeasured on a real site): rebuilt from the live page's rendered HTML, flagged, and held at the transform gate until the owner has checked each one. Rows: elementor, divi, gutenberg-libs, other-builders.",
];
top.forEach((t, i) => L.push(`${i + 1}. ${t}`));
L.push("");
L.push(`## 2. Parity matrix`, "");
L.push(`Columns: the WordPress feature · its EmDash 1.5 home (evidence level in italics when it is not from source) · what the kit does now, with file references · the gap and how to close it · effort / risk · priority · how many of the 2 real sites used it.`, "");
for (const a of areas) {
	L.push(`### ${a}`, "");
	L.push(`| WP feature | EmDash 1.5 home | Kit status + refs | Gap & approach | Effort / risk | Pri | Sites |`);
	L.push(`|---|---|---|---|---|---|---|`);
	for (const r of rows.filter((x) => x.area === a)) {
		L.push(`| ${esc(r.feature)} <sub>\`${r.id}\`</sub> | ${esc(r.emdash)}${CONF[r.emdashConfidence]} | ${STATUS[r.status]}: ${esc(r.kit)} | ${esc(r.gap)} | ${r.effort ? `${r.effort} / ${r.risk}` : "—"} | ${r.priority || "—"} | ${r.sitesUsed || "—"} |`);
	}
	L.push("");
}
L.push(`## 3. Prioritized backlog`, "");
L.push(`**P0** is what a typical small-business site with a blog needs to call the migration “100%”. **P1** covers common plugins and builders. **P2** covers fidelity details and rarer features. Items in progress elsewhere are marked as such.`, "");
L.push(`| # | Pri | Item | Rows | Effort | Notes |`, `|---|---|---|---|---|---|`);
for (const [rank, pri, title, ids, effort, notes] of backlog) L.push(`| ${rank} | ${pri} | ${esc(title)} | ${ids.map((i) => `\`${i}\``).join(", ")} | ${effort} | ${esc(notes)} |`);
L.push("");
L.push(`**P2:** ${p2.map((i) => `\`${i}\``).join(", ")}. Each row in §2 gives its approach.`, "");
L.push(`**Out of scope (detected, migration stops for an owner decision):**`, "");
for (const r of oos) L.push(`- **${r.feature}**: ${r.gap}`);
L.push("");
L.push(`**Suggested order.** Start with items 2 and 3 (S/M): they make every remaining gap visible as a red gate instead of a silent loss. Then items 1, 4, 5, 6 and 7 together as one “blog” milestone, tested against a fixture blog and a real WordPress blog. After that, item 8 and the P1 items in the order the next client sites need them.`, "");
L.push(`## 4. Verification notes`, "");
L.push(`**Confirmed in the installed EmDash 1.5.0 source** (\`emdash/src\`, \`@emdash-cms/*\`; read 2026-11-20):`, "");
L.push(`- 17 field types and flat-only repeaters (\`schema/types.ts\`).`);
L.push(`- Entry system columns: no parent, menu_order or template; statuses \`draft|published|archived\` (\`schema/registry.ts\`, \`query.ts\`).`);
L.push(`- Taxonomy, menu, widget, section and byline tables plus their REST routes (\`astro/routes/api/{taxonomies,menus,widget-areas,sections}\`).`);
L.push(`- Content create/update accept \`bylines\` and \`publishedAt\`; \`publishedAt\` requires \`content:publish_any\` (\`api/schemas/content.ts\`).`);
L.push(`- Comments: table, statuses, one-level threading, Turnstile; the public route stamps the current time and the admin routes only moderate; the Exporter-plugin import (\`importCommentsFromPlugin\`) reads the live WordPress site; site transfer needs an empty target. The kit adds an admin-only import route (docs/spikes/comments-findings.md).`);
L.push(`- Redirects (301/302/307/308/410/451, \`[param]\` patterns, 404 log) and auto-redirects on slug change.`);
L.push(`- \`SiteSettings\` keys: \`title tagline logo favicon url staging postsPerPage dateFormat timezone social seo{titleSeparator defaultOgImage robotsTxt disallowAiTraining googleVerification bingVerification}\` (\`settings/types.ts\`).`);
L.push(`- Sitemaps cover only collections that are both SEO-enabled and routable, with no taxonomy or author sitemaps; the robots.txt route exists.`);
L.push(`- **No RSS/Atom anywhere in src.**`);
L.push(`- FTS5 search (seed \`supports: search\` + a searchable field; blocks fields cannot be searchable); widget areas (seed \`widgetAreas\`, \`props\` for components); the bounded 404 log — checked in an in-memory spike on 2026-11-21.`);
L.push(`- FTS5 search; media allowlist (no SVG by default; PDF, audio and video allowed; other types only through a file field's \`allowedMimeTypes\` and the upload's \`fieldId\`); media has \`caption\` but no title/description; non-image files are served as attachments.`);
L.push(`- No private or password status; EmDash's WordPress importers make password-protected posts drafts; the sitemap leaves \`seo_no_index\` entries out; anonymous content REST reads are refused (\`requirePerm\`).`);
L.push(`- Scheduled publishing runs on the Worker \`scheduled()\` handler.`);
L.push(`- \`page:fragments\` hook is trusted-only; \`page:metadata\` exists.`);
L.push(`- Email has no attachments.`);
L.push(`- Seed keys: \`settings collections blockTypes relations taxonomies menus redirects widgetAreas sections bylines content\`; there are no seed keys for comments or SEO.`);
L.push(`- EmDash's own WordPress import paths: WXR upload; Exporter-plugin import, which writes SEO into \`seo_title\`/\`seo_description\` content fields; CLI. The Exporter-plugin import is the only one that imports comments. None of them imports redirects or widgets.`);
L.push(`- \`@emdash-cms/gutenberg-to-portable-text\` handles core audio/file/table/embed among others.`, "");
L.push(`**Docs only (not re-checked in source):** atproto/Atmosphere login; the Docs MCP and agent skills; “shortcodes are not expanded” by the converter.`, "");
L.push(`**Kit status** comes from reading the kit source at the paths cited. Line numbers are approximate (~). The real-site columns come from each site's audit, extract, transform and verify reports and \`decisions.md\`, and are counts only.`, "");
L.push(`**Assumed or still to verify before code depends on it** (record each result in \`docs/spikes/\`):`, "");
L.push(`- ~~Token scopes and \`publishedAt\`~~: verified 2026-11-20 — \`content:publish_any\` is a role permission (Editor+), not a token scope; bylines need the \`admin\` token scope (docs/spikes/blog-findings.md).`);
L.push(`- ~~REST schedule endpoint~~: \`POST /content/{c}/{id}/schedule\` {scheduledAt}, verified 2026-11-20.`);
L.push(`- ~~A write path for comments~~: verified 2026-11-21 — neither fits (site import needs an empty site; \`importCommentsFromPlugin\` is not exported and its route fetches from the live WordPress); the kit's own route writes pending rows, EmDash's bulk moderation approves (docs/spikes/comments-findings.md).`);
L.push(`- Which \`options\` keys the Exporter returns: timezone, date_format and posts_per_page were not confirmed (M3 lists identity, front page, permalink structure and site icon).`);
L.push(`- Which WordPress widget REST routes work with an application password on WP ≥ 5.8 (\`wp/v2/sidebars\`, \`wp/v2/widgets\`, \`wp/v2/menu-items\` need \`edit_theme_options\`; extract reads them and notes a refusal — not yet run on a real site).`);
L.push(`- ~~Date-based permalinks in \`urlPattern\`~~: verified 2026-11-20 — one placeholder per path segment (schema/url-pattern.ts); the kit stores the WordPress path as the slug with \`/{slug}\`.`);
L.push(`- ~~Whether EmDash's \`buildWebSiteJsonLd\` emits a SearchAction~~: verified 2026-11-21 — no SearchAction anywhere in EmDash 1.5 (docs/spikes/site-features-findings.md).`);
L.push(`- ~~The kit's handling of WordPress core \`[caption]\`, \`[audio]\`, \`[video]\`, \`[embed]\` shortcodes~~: handled in pages and posts since 2026-11-21 (fixture plugin-shortcodes); \`[playlist]\` stays flagged.`);
L.push(`- Password-protected pages, linked documents and form uploads (2026-11-21) are unit-tested and pass \`astro check\` in a generated project; not yet loaded into a live EmDash or deployed.`);
L.push("");
writeFileSync(`${OUT}/wp-to-emdash.md`, L.join("\n"));
console.log(JSON.stringify(summary));
